import * as THREE from 'three';
const cams = {};
function cam(name, pos, target, fov = 55) {
  const c = new THREE.PerspectiveCamera(fov, innerWidth / innerHeight, 0.1, 2000);
  c.position.copy(pos); c.up.set(0, 1, 0); c.lookAt(target); c.updateMatrixWorld(true);
  c.userData.tag = name; cams[name] = c; return c;
}
export function buildRig(scene, player) {
  const p = player.position;
  cam('default', p.clone().add(new THREE.Vector3(0, 3.5, 7)), p.clone().add(new THREE.Vector3(0, 1, 0)));      // player 1/3-1/2 of frame height
  cam('close',   p.clone().add(new THREE.Vector3(1.5, 1.8, 2.4)), p.clone().add(new THREE.Vector3(0, 1.2, 0))); // within ~3 m
  cam('wide',    p.clone().add(new THREE.Vector3(-120, 60, 220)), p.clone(), 45);                              // >= 200 m out
  cam('top',     p.clone().add(new THREE.Vector3(0, 90, 0.01)), p.clone(), 40);
  const pitch = THREE.MathUtils.degToRad(27), eyePos = p.clone().add(new THREE.Vector3(0, 1.6, 0));            // eye height, 25-30 deg down
  cam('player-eye', eyePos, eyePos.clone().add(new THREE.Vector3(0, -Math.sin(pitch), -Math.cos(pitch))));
  Object.values(cams).forEach(c => scene.add(c));    // in the graph so scene checks can find them by tag
  return cams;
}
export function debugCamera(name, renderer, scene, setActive) {
  const c = cams[name];
  if (!c) throw new Error('unknown camera: ' + name);   // never fall through to the default view
  c.aspect = innerWidth / innerHeight; c.updateProjectionMatrix(); c.updateMatrixWorld(true);
  setActive(c);                                         // first-person stays a mode toggle; it resumes on the next step()
  renderer.render(scene, c);                            // synchronous re-render, not the next rAF
  return c;
}
